219	func (r registryTemplate) Download(ctx context.Context) (workspace.Template, error) {
220		templateBytes, err := r.registry.DownloadTemplate(ctx, r.t.DownloadURL)
221		if err != nil {
222			return workspace.Template{}, fmt.Errorf("failed to download from %q: %w", r.t.DownloadURL, err)
223		}
224		defer contract.IgnoreClose(templateBytes)
225		templateDir, err := os.MkdirTemp("", "pulumi-template-")
226		if err != nil {
227			return workspace.Template{}, fmt.Errorf("failed to make temporary directory: %w", err)
228		}
