// ResolveTemplateFromName resolves a registry template from user input. User input may be
// in the following forms:
//
//	<source>/<publisher>/<name> -> [<source>/<publisher>/<name>]
//
//	<publisher>/<name>          -> [private/<publisher>/<name>, pulumi/<publisher>/<name>]
//
//	<name>                      -> discovered via [Registry.ListTemplates]
//
// If version is non-nil, the specific version is fetched via [Registry.GetTemplate];
// otherwise the latest is used.
//
// The returned error will include [NotFoundError] (checkable via errors.Is) if and only if
// ResolveTemplateFromName has determined that the registry does not contain a matching
// template. The single exception is the single-part case with a version that isn't found:
// in that case the error message contains "version <X.Y.Z> was not found".
//
// If ResolveTemplateFromName could not parse name into a fragment kind, it will return an
// error that includes [InvalidIdentifierError] (checkable via errors.As).
func ResolveTemplateFromName(
	ctx context.Context, reg Registry, name string, version *semver.Version,
) (apitype.TemplateMetadata, error) {
	parts := strings.Split(name, "/")
	switch len(parts) {
	case 3:
		return reg.GetTemplate(ctx, parts[0], parts[1], parts[2], version)
	case 2:
		// First check on "private".
		tmpl, err := reg.GetTemplate(ctx, "private", parts[0], parts[1], version)
		if err == nil {
			return tmpl, nil
		} else if !errors.Is(err, ErrNotFound) && !errors.Is(err, ErrUnauthorized) && !errors.Is(err, ErrForbidden) {
			return apitype.TemplateMetadata{}, fmt.Errorf("unable to check on private/%s: %w", name, err)
		}

		// Then check on "pulumi".
		tmpl, err = reg.GetTemplate(ctx, "pulumi", parts[0], parts[1], version)
		if err == nil {
			return tmpl, nil
		} else if !errors.Is(err, ErrNotFound) {
			return apitype.TemplateMetadata{}, fmt.Errorf("unable to check on pulumi/%s: %w", name, err)
		}

		// Both "private" and "pulumi" didn't exist, so we have successfully resolved to NotFound.
		return apitype.TemplateMetadata{}, fmt.Errorf("could not resolve %s: %w", name, ErrNotFound)
	case 1:
		// Templates don't carry version information in the list response, so we use
		// ListTemplates only to discover the source and publisher. When a specific
		// version is requested, we fetch it with GetTemplate below.
		var best *apitype.TemplateMetadata
		priority := func(m apitype.TemplateMetadata) int {
			switch {
			case m.Source == "private":
				return 2
			case m.Source == "pulumi" && m.Publisher == "pulumi":
				return 1
			default:
				return 0
			}
		}
		for meta, err := range reg.ListTemplates(ctx, ListTemplatesOptions{Name: name}) {
			if err != nil {
				return apitype.TemplateMetadata{}, err
			}
			meta := meta
			if best == nil || priority(meta) > priority(*best) {
				best = &meta
			}
		}

		if best == nil {
			var versionStr string
			if version != nil {
				versionStr = "@" + version.String()
			}
			return apitype.TemplateMetadata{}, fmt.Errorf(
				"%s%s does not match a registry template: %w", name, versionStr, ErrNotFound)
		}

		if version == nil {
			return *best, nil
		}

		m, err := reg.GetTemplate(ctx, best.Source, best.Publisher, best.Name, version)
		if err == nil {
			return m, nil
		}
		if errors.Is(err, ErrNotFound) {
			return apitype.TemplateMetadata{}, fmt.Errorf(
				"%s/%s/%s exists, but version %s was not found: %w",
				best.Source, best.Publisher, best.Name, version, ErrNotFound)
		}
		return apitype.TemplateMetadata{}, err
	default:
		return apitype.TemplateMetadata{}, InvalidIdentifierError{name}
	}
