	assert.True(t, errors.Is(err, ErrNotFound))

	// two-part private precedence
	r = mockRegistry{getTemplate: func(ctx context.Context, s, p, n string, v *semver.Version) (apitype.TemplateMetadata, error) {
		if s == "private" {
			return apitype.TemplateMetadata{Source: s, Publisher: p, Name: n}, nil
		}
		t.Fatal("should not reach pulumi")
		return apitype.TemplateMetadata{}, nil
	}}
