	r = mockRegistry{getTemplate: func(ctx context.Context, s, p, n string, v *semver.Version) (apitype.TemplateMetadata, error) {
		if s == "private" {
			return apitype.TemplateMetadata{}, ErrNotFound
		}
		return apitype.TemplateMetadata{Source: s}, nil
	}}
	tm, err = ResolveTemplateFromName(ctx, r, "pub/name", nil)
	require.NoError(t, err)
	assert.Equal(t, "pulumi", tm.Source)

